def compute(vars):
    old_revenue = vars["v1"]
    new_revenue = vars["v2"]
    decrease = old_revenue - new_revenue
    return {
        "value": decrease,
        "trace": {
            "old_revenue": old_revenue,
            "new_revenue": new_revenue,
            "decrease": decrease,
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": None
            }
        }
    }
